const w = p.width; const d = p.depth; const h = p.height; const t = p.wall; 
const gap = 0.4; const tabH = 4; const tabW = 12; const tabD = 1.5;

const mainBox = drawRoundedRectangle(w, d, 3).sketchOnPlane('XY').extrude(h)
  .cut(drawRoundedRectangle(w - 2 * t, d - 2 * t, 2).sketchOnPlane('XY', t).extrude(h));

const tab = drawRectangle(tabW, tabD).sketchOnPlane('XY', h - 6).extrude(tabH);
const box = mainBox.fuse(tab.clone().translateY(d/2 - t/2 - 0.5)).fuse(tab.clone().translateY(-d/2 + t/2 + 0.5));

const lidTop = drawRoundedRectangle(w + 1, d + 1, 3.5).sketchOnPlane('XY', h).extrude(t);
const lidInner = drawRoundedRectangle(w - t, d - t, 2.5).sketchOnPlane('XY', h - t).extrude(t);
const lidWall = drawRoundedRectangle(w - t, d - t, 2.5).sketchOnPlane('XY', h - t - 4).extrude(5);
const lidPocket = drawRoundedRectangle(w - 2 * t - gap, d - 2 * t - gap, 2).sketchOnPlane('XY', h - 0.5).extrude(t + 5);

const lidBase = lidTop.fuse(lidInner).fuse(lidWall).cut(lidPocket);
const cutTab = drawRectangle(tabW + gap, tabD + gap).sketchOnPlane('XY', h - 6 - gap).extrude(tabH + 2 * gap);
const lid = lidBase.cut(cutTab.clone().translateY(d/2 - t/2 - 0.5)).cut(cutTab.clone().translateY(-d/2 + t/2 + 0.5));

return { box: box, lid: lid };
